package com.jnapanam.sportszone.content.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="announcements")public class Announcement{@Id private UUID id;@Column(nullable=false,length=180)private String title;@Column(nullable=false,columnDefinition="TEXT")private String body;@Column(nullable=false)private int priority;@Column(name="publish_from",nullable=false)private Instant publishFrom;@Column(name="publish_until")private Instant publishUntil;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ContentStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Announcement(){}public Announcement(String t,String b,int p,Instant from,Instant until){id=UUID.randomUUID();update(t,b,p,from,until);status=ContentStatus.DRAFT;createdAt=Instant.now();updatedAt=createdAt;}public void update(String t,String b,int p,Instant from,Instant until){title=t.trim();body=b.trim();priority=p;publishFrom=from;publishUntil=until;updatedAt=Instant.now();}public void status(ContentStatus s){status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public String getTitle(){return title;}public String getBody(){return body;}public int getPriority(){return priority;}public Instant getPublishFrom(){return publishFrom;}public Instant getPublishUntil(){return publishUntil;}public ContentStatus getStatus(){return status;}}
